<?php $pageTitle='Create Account';$theme='pink';require_once 'includes/user-auth.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']);$email=trim($_POST['email']);$phone=trim($_POST['phone']);$pass=$_POST['password'];if($name&&filter_var($email,FILTER_VALIDATE_EMAIL)&&strlen($pass)>=6){try{$q=$pdo->prepare('INSERT INTO users(name,email,phone,password) VALUES(?,?,?,?)');$q->execute([$name,$email,$phone,password_hash($pass,PASSWORD_DEFAULT)]);$_SESSION['user_id']=$pdo->lastInsertId();header('Location: account.php');exit;}catch(PDOException $e){$error='That email is already registered.';}}else{$error='Please provide valid details and a password of at least 6 characters.';}}include 'includes/header.php';?><section class="py-5"><div class="col-lg-5 mx-auto"><div class="content-card p-4 p-md-5"><h2>Create your account</h2><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?><form method="post"><input name="name" class="form-control mb-3" placeholder="Full name" required><input name="email" type="email" class="form-control mb-3" placeholder="Email" required><input name="phone" class="form-control mb-3" placeholder="Phone"><input name="password" type="password" class="form-control mb-3" placeholder="Password" required minlength="6"><button class="btn btn-brand w-100">Create Account</button></form><p class="mt-3 mb-0">Already registered? <a href="login.php">Login</a></p></div></div></section><?php include 'includes/footer.php';?>
